-- ----------------------------
-- Table structure for coupon
-- ----------------------------
DROP TABLE IF EXISTS `coupon`;
CREATE TABLE `coupon`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '优惠券ID',
  `coupon_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '优惠券编码，唯一标识',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '优惠券名称',
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '优惠券类型：1-现金券，2-折扣券，3-满减券',
  `amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额/折扣值',
  `min_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '最低消费金额',
  `total_num` int NOT NULL DEFAULT -1 COMMENT '总数量，-1表示不限',
  `received_num` int NOT NULL DEFAULT 0 COMMENT '已领取数量',
  `used_num` int NOT NULL DEFAULT 0 COMMENT '已使用数量',
  `per_limit` int NOT NULL DEFAULT 1 COMMENT '每人限领数量，-1表示不限',
  `valid_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '有效期类型：1-固定时间，2-领取后N天',
  `valid_days` int NULL DEFAULT NULL COMMENT '领取后有效天数',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `source` tinyint(1) NOT NULL DEFAULT 1 COMMENT '来源：1-系统，2-活动，3-充值，4-消费',
  `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '描述',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序值',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1-启用，2-停用，3-过期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`coupon_code` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_time`(`start_time` ASC, `end_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '优惠券主表' ROW_FORMAT = Dynamic;

