-- ----------------------------
-- Table structure for news
-- ----------------------------
DROP TABLE IF EXISTS `news`;
CREATE TABLE `news`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '新闻ID',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '描述',
  `excerpt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '摘要',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '图片URL',
  `author` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '作者',
  `source` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源',
  `views` int NULL DEFAULT 0 COMMENT '浏览量',
  `likes` int NULL DEFAULT 0 COMMENT '点赞数',
  `shares` int NULL DEFAULT 0 COMMENT '分享数',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标签',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_title`(`title` ASC) USING BTREE,
  INDEX `idx_category`(`category` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_views`(`views` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '新闻表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of news
-- ----------------------------
INSERT INTO `news` VALUES (1, '农业农村部发布2026年乡村振兴重点工作', '农业农村部近日印发了关于做好2026年全面推进乡村振兴重点工作的实施意见，提出了多项惠农政策。', '本文介绍了2026年乡村振兴的重点工作方向和具体措施。', '<h2>一、总体要求</h2><p>以习近平新时代中国特色社会主义思想为指导，全面贯彻党的二十大精神...</p><p>坚持农业农村优先发展，坚持城乡融合发展，畅通城乡要素流动...</p><h2>二、抓紧抓好粮食和重要农产品稳产保供</h2><p>确保全年粮食产量保持在1.3万亿斤以上...</p><p>加强耕地保护和质量建设，确保耕地保有量不少于18亿亩...</p><h2>三、巩固拓展脱贫攻坚成果</h2><p>强化防止返贫动态监测，确保不发生规模性返贫...</p><p>稳定完善帮扶政策，加大对重点帮扶县支持力度...</p>', '/imgs/news/news1.png', '农业部', '农业农村部官网', 1522, 287, 45, '乡村振兴,惠农政策,粮食安全', 'policy', '2026-05-08 19:33:51', '2026-05-08 19:49:07');
INSERT INTO `news` VALUES (2, '数字农业新技术助力春耕生产', '今年春耕期间，各地积极推广智慧农业技术，无人机播种、精准灌溉等新技术成为田间地头的新亮点。', '数字农业技术正在改变传统的农业生产方式。', '<h2>智慧农业春耕新气象</h2><p>在东北黑土地上，大型农机具加装了北斗导航系统，实现了精准播种...</p><p>农户通过手机APP就能实时查看土壤墒情、气象预报等信息...</p><h2>无人机成为新农具</h2><p>植保无人机每天作业面积可达300亩，效率是传统人工的20倍...</p><p>智慧农业不仅提高了生产效率，还大幅降低了成本...</p>', '/imgs/news/news2.png', '农业科技报', '农业科技报社', 2362, 414, 79, '数字农业,智慧农业,春耕,农业科技', 'technology', '2026-05-08 19:33:51', '2026-05-08 19:49:13');
INSERT INTO `news` VALUES (3, '农产品质量安全监管再加码', '农业农村部、市场监管总局联合部署2026年农产品质量安全监管工作，确保人民群众\"舌尖上的安全\"。', '多部门联合加强农产品质量安全监管。', '<h2>强化源头监管</h2><p>加强对农产品生产基地的监管，严格执行农药使用间隔期制度...</p><p>推进农产品质量安全追溯体系建设，实现来源可查、去向可追...</p><h2>加大抽检力度</h2><p>全年计划抽检农产品样品不少于150万批次...</p><p>建立健全农产品质量安全风险评估机制...</p><h2>严厉打击违法行为</h2><p>深入开展农产品质量安全专项整治行动...</p><p>建立健全举报奖励制度，鼓励社会监督...</p>', '/imgs/news/news3.png', '食品安全网', '食品安全网', 1890, 156, 32, '质量安全,农产品监管,食品安全', 'safety', '2026-05-08 19:33:51', '2026-05-08 19:49:14');
INSERT INTO `news` VALUES (4, '农村电商蓬勃发展，农产品上行渠道畅通', '2026年一季度农村电商继续保持快速增长态势，农产品网络销售额突破5000亿元。', '农村电商成为农产品销售的重要渠道。', '<h2>电商助农成效显著</h2><p>各大电商平台纷纷开设助农专区，帮助农户拓展销售渠道...</p><p>直播带货成为农产品销售新模式，单场销售额屡创新高...</p><h2>物流基础设施完善</h2><p>农村物流配送网络不断延伸，实现行政村快递覆盖率超95%...</p><p>冷链物流体系建设加快，保障生鲜农产品新鲜送达...</p><h2>品牌建设持续推进</h2><p>各地加强农产品品牌培育，打造区域公用品牌...</p><p>推动农产品标准化生产，提升产品品质和附加值...</p>', '/imgs/news/news4.png', '电商周刊', '电商周刊', 3200, 520, 156, '农村电商,农产品上行,直播带货', 'ecommerce', '2026-05-08 19:33:51', '2026-05-08 19:49:16');
INSERT INTO `news` VALUES (5, '新型职业农民培育计划全面启动', '农业农村部启动\"十四五\"新型职业农民培育计划，今年将培训高素质农民100万人。', '培养有文化、懂技术、善经营、会管理的新型职业农民。', '<h2>培训内容丰富多样</h2><p>涵盖现代农业技术、农产品营销、农村电商、合作社经营等内容...</p><p>采用理论教学与实践操作相结合的培训模式...</p><h2>政策支持力度加大</h2><p>对参训农民给予培训补贴，支持农民参加学历教育...</p><p>建立新型职业农民职称评审制度...</p><h2>服务保障不断完善</h2><p>搭建农民培训与就业对接平台...</p><p>建立跟踪服务机制，为参训农民提供持续的技术指导...</p>', '/imgs/news/news5.png', '农民日报', '农民日报社', 1450, 289, 67, '职业农民,农民培训,人才振兴', 'technology', '2026-05-08 19:33:51', '2026-05-08 19:49:19');
INSERT INTO `news` VALUES (6, '乡村旅游持续升温，农家乐转型升级', '今年春季，乡村旅游市场火爆，特色民宿、农事体验等新业态成为游客新宠。', '乡村旅游正在从观光型向体验型转变。', '<h2>乡村旅游新业态涌现</h2><p>农家乐向精品民宿转型升级，特色民宿成为住宿新选择...</p><p>农事体验、研学旅行、康养度假等新业态蓬勃发展...</p><h2>基础设施建设加强</h2><p>乡村旅游基础设施不断完善，道路、停车、标识标牌等配套齐全...</p><p>智慧旅游系统覆盖主要乡村旅游景区...</p><h2>文化内涵不断丰富</h2><p>深挖乡村文化资源，打造具有地方特色的旅游产品...</p><p>非遗传承与乡村旅游有机结合，提升游客体验感...</p>', '/imgs/news/news6.png', '旅游时报', '旅游时报社', 2181, 398, 89, '乡村旅游,民宿,农事体验', 'tourism', '2026-05-08 19:33:51', '2026-05-08 19:49:21');
INSERT INTO `news` VALUES (7, '农村金融创新服务乡村振兴', '金融机构创新推出多种农村金融产品和服务模式，为乡村振兴提供有力金融支撑。', '农村金融产品不断丰富，服务更加便捷。', '<h2>信贷产品创新</h2><p>推出\"农机贷\"\"春耕贷\"\"收粮贷\"等特色信贷产品...</p><p>简化贷款流程，降低融资成本，满足农户多样化资金需求...</p><h2>保险保障增强</h2><p>扩大农业保险覆盖面，开发特色农产品保险...</p><p>天气指数保险、农产品价格保险等创新产品不断涌现...</p><h2>数字普惠金融发展</h2><p>移动支付在农村地区普及，农户足不出户即可办理金融业务...</p><p>农村信用体系建设加快，农户贷款更加便捷...</p>', '/imgs/foods/news8.png', '金融时报', '金融时报社', 1670, 234, 54, '农村金融,普惠金融,乡村振兴', 'finance', '2026-05-08 19:33:51', '2026-05-08 19:56:45');
INSERT INTO `news` VALUES (8, '品牌强农战略深入推进', '各地深入实施品牌强农战略，打造了一批具有市场竞争力的农产品品牌。', '品牌建设成为提升农产品附加值的重要途径。', '<h2>区域公用品牌建设</h2><p>打造\"一县一品\"区域公用品牌，提升产品知名度和市场竞争力...</p><p>建立品牌授权使用和退出机制，确保品牌品质...</p><h2>企业品牌培育</h2><p>支持龙头企业做大做强，培育一批具有行业影响力的企业品牌...</p><p>引导农户加入产业化经营，分享品牌溢价收益...</p><h2>品牌营销推广</h2><p>举办农产品品牌推介活动，提升品牌影响力...</p><p>利用电商平台和新媒体进行品牌营销，拓展销售渠道...</p>', '/imgs/foods/news7.png', '农业品牌网', '农业品牌研究中心', 1935, 347, 78, '品牌建设,品牌强农,农产品品牌', 'marketing', '2026-05-08 19:33:51', '2026-05-08 19:56:48');
INSERT INTO `news` VALUES (9, '界哥', '界哥', '', '界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥界哥', NULL, '界哥', NULL, 0, 0, 0, '界哥', 'policy', '2026-05-17 16:57:31', '2026-05-17 16:57:31');

-- ----------------------------
-- Table structure for order_products
-- ----------------------------
DROP TABLE IF EXISTS `order_products`;
CREATE TABLE `order_products`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单编号',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `product_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称',
  `quantity` int NOT NULL COMMENT '数量',
  `price` decimal(10, 2) NOT NULL COMMENT '单价',
  `total_price` decimal(10, 2) NOT NULL COMMENT '小计',
  `sku_id` bigint NULL DEFAULT NULL COMMENT 'SKU ID',
  `sku_attributes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT 'SKU属性',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_id`(`order_id` ASC) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE,
  CONSTRAINT `fk_order_products_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 97 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '订单商品表' ROW_FORMAT = Dynamic;

