-- ----------------------------
-- View structure for v_pending_products
-- ----------------------------
DROP VIEW IF EXISTS `v_pending_products`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_pending_products` AS select `p`.`id` AS `id`,`p`.`name` AS `name`,`p`.`description` AS `description`,`p`.`price` AS `price`,`p`.`original_price` AS `original_price`,`p`.`image` AS `image`,`p`.`category` AS `category`,`p`.`stock` AS `stock`,`p`.`unit` AS `unit`,`p`.`weight` AS `weight`,`p`.`origin` AS `origin`,`p`.`brand` AS `brand`,`p`.`is_hot` AS `is_hot`,`p`.`is_new` AS `is_new`,`p`.`is_recommend` AS `is_recommend`,`p`.`views` AS `views`,`p`.`sales` AS `sales`,`p`.`status` AS `status`,`p`.`merchant_id` AS `merchant_id`,`p`.`submit_time` AS `submit_time`,`p`.`create_time` AS `create_time`,`u`.`name` AS `merchant_name`,`u`.`phone` AS `merchant_phone`,`u`.`avatar` AS `merchant_avatar` from (`products` `p` left join `users` `u` on((`p`.`merchant_id` = `u`.`id`))) where (`p`.`status` = 'pending') order by `p`.`submit_time` desc;

SET FOREIGN_KEY_CHECKS = 1;
